static int udp_checksum_valid(void *pkt)
{
	struct iip_l4_ip4_pseudo_hdr pseudo;
	uint8_t *b[2];
	uint16_t l[2];
	uint16_t supplied = ii_ntohs(PB_UDP(pkt)->csum_be);

	pseudo.ip4_src_be = PB_IP4(pkt)->src_be;
	pseudo.ip4_dst_be = PB_IP4(pkt)->dst_be;
	pseudo.pad = 0;
	pseudo.proto = 17;
	pseudo.len_be = PB_UDP(pkt)->len_be;
	b[0] = (uint8_t *)&pseudo;
	b[1] = (uint8_t *)PB_UDP(pkt);
	l[0] = sizeof(pseudo);
	l[1] = PB_UDP_TOTAL_LEN(pkt);
	return supplied == test_netcsum16(b, l, 2, supplied);
}

static void *fixture_udp_packet(struct fixture *f, const uint8_t *payload,
		uint16_t payload_len)
{
	void *data = NULL;
	void *pkt;

	if (payload_len) {
		data = iip_ops_pkt_alloc(&f->state);
		assert(data);
		memcpy(iip_ops_pkt_get_data(data, &f->state), payload, payload_len);
		iip_ops_pkt_set_len(data, payload_len, &f->state);
	}
	memcpy(f->state.local_mac, f->peer_mac, 6);
	f->state.local_ip4_be = ii_htonl(f->conn->dst_ip[0]);
	assert(iip_udp_ipv4_ethernet_send_copy(f->ws, f->peer_mac, ii_htonl(f->conn->dst_ip[0]),
			ii_htons(20000), f->local_mac, ii_htonl(f->conn->src_ip[0]),
			ii_htons(10000), 0, data ? iip_ops_pkt_get_data(data, &f->state) : NULL, payload_len, &f->state) == 0);
	iip_ops_pkt_free(data, &f->state);
	assert(f->state.out_cnt == 1);
	pkt = f->state.out[0];
	f->state.out_cnt = 0;
	return pkt;
}

/*
 * Independent one's-complement sum over the IPv4 pseudo header and the UDP
 * datagram, with the checksum field taken as zero.  An odd-length datagram is
 * padded with one zero octet for the computation only.
 */
static uint16_t udp_reference_sum(void *pkt)
{
	const uint8_t *ip = (const uint8_t *)PB_IP4(pkt);
	const uint8_t *udp = (const uint8_t *)PB_UDP(pkt);
	uint16_t udp_len = PB_UDP_TOTAL_LEN(pkt);
	uint32_t sum = 0;
	uint16_t i;

	for (i = 12; i < 20; i += 2)
		sum += (uint32_t)ip[i] << 8 | ip[i + 1];
	sum += 17;
	sum += udp_len;
	for (i = 0; i < udp_len; i += 2) {
		uint16_t hi = udp[i];
		uint16_t lo = i + 1 < udp_len ? udp[i + 1] : 0;
		if (i == 6)
			continue; /* checksum field */
		sum += (uint32_t)hi << 8 | lo;
	}
	while (sum >> 16)
		sum = (sum & 0xffff) + (sum >> 16);
	return (uint16_t)sum;
}

/*
 * RFC 768 and RFC 1122 Section 4.1.3.4: the checksum covers the pseudo header
 * (addresses, protocol, UDP length) and the UDP header and data.  Datagrams
 * with a nonzero, incorrect checksum MUST be silently discarded.
 */
static enum result test_udp_checksum_validation(const char **why)
{
	static const uint8_t payload[7] = { 0xff, 0xff, 0x80, 0x01, 0x7f, 0xfe, 0x55 };
	struct fixture f;
	void *pkt;
	uint16_t expected;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	/* Odd length and carry-producing words exercise padding and folding. */
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	expected = (uint16_t)~udp_reference_sum(pkt);
	if (!expected)
		expected = 0xffff;
	if (ii_ntohs(PB_UDP(pkt)->csum_be) != expected) {
		*why = "transmitted UDP checksum does not match the pseudo-header computation";
		return RESULT_FAIL;
	}
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 1) {
		*why = "a UDP datagram with a valid checksum was not delivered";
		return RESULT_FAIL;
	}

	/* Corrupt only the payload: the nonzero checksum is now wrong. */
	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP_PAYLOAD(pkt)[0] ^= 0x01;
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 0 ||
			output_count_ethertype(&f.state, 0x0800) != 0) {
		*why = "a UDP datagram with an incorrect checksum was not silently discarded";
		return RESULT_FAIL;
	}

	/* Change only the IPv4 source address: the pseudo header no longer
	 * matches, although the UDP header and data are unchanged. */
	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_IP4(pkt)->src_be = ii_htonl(f.conn->dst_ip[0] + 1);
	update_ip4_checksum(pkt);
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 0) {
		*why = "the UDP checksum did not cover the IPv4 pseudo header";
		return RESULT_FAIL;
	}
	free_output(&f.state);
	return RESULT_PASS;
}

/*
 * RFC 768: a transmitted checksum of zero means that no checksum was
 * generated.  Discarding such datagrams is only an optional, configurable
 * behavior (RFC 1122 Section 4.1.3.4), so report a discard as TODO.
 */
static enum result test_udp_zero_checksum_receive(const char **why)
{
	static const uint8_t payload[4] = { 1, 2, 3, 4 };
	struct fixture f;
	void *pkt;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP(pkt)->csum_be = 0;
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 1) {
		*why = "a UDP datagram without a checksum (zero) was discarded";
		return RESULT_TODO;
	}
	return RESULT_PASS;
}

/*
 * RFC 768: if the computed checksum is zero, it is transmitted as all ones
 * (0xffff), because zero on the wire means that no checksum was generated.
 * Choose the last payload word so that the computed checksum is zero.
 */
static enum result test_udp_zero_result_checksum(const char **why)
{
	uint8_t payload[8] = { 0x12, 0x34, 0x56, 0x78, 0x9a, 0xbc, 0, 0 };
	struct fixture f;
	void *pkt;
	uint16_t word;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	word = (uint16_t)~udp_reference_sum(pkt);
	iip_ops_pkt_free(pkt, &f.state);
	payload[6] = (uint8_t)(word >> 8);
	payload[7] = (uint8_t)word;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	if ((uint16_t)~udp_reference_sum(pkt) != 0) {
		*why = "test construction error: computed checksum is not zero";
		return RESULT_FAIL;
	}
	if (ii_ntohs(PB_UDP(pkt)->csum_be) != 0xffff) {
		*why = "a computed UDP checksum of zero was not transmitted as 0xffff";
		return RESULT_FAIL;
	}
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 1) {
		*why = "a UDP datagram carrying checksum 0xffff was not delivered";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

/*
 * RFC 1122 Section 4.1.3.1: a UDP datagram for a port with no listener
 * SHOULD be answered with ICMP Destination Unreachable, code 3, quoting the
 * IPv4 header and the first 8 octets of the datagram.  When the datagram is
 * delivered to the application, the API has no closed-port state and the
 * requirement does not apply.
 */
static enum result test_udp_port_unreachable(const char **why)
{
	static const uint8_t payload[4] = { 1, 2, 3, 4 };
	struct fixture f;
	void *pkt, *reply;
	uint8_t quoted[sizeof(struct iip_ip4_hdr) + 8];

	if (!fixture_init(&f))
		return RESULT_FAIL;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	memcpy(quoted, PB_IP4(pkt), sizeof(quoted));
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 0) {
		*why = "the UDP API delivers every datagram to the application; no port is closed";
		return RESULT_SKIP;
	}
	if (output_count_ethertype(&f.state, 0x0800) == 0) {
		*why = "a datagram for a port with no listener was discarded without ICMP Port Unreachable (SHOULD)";
		return RESULT_TODO;
	}
	reply = output_nth_ethertype(&f.state, 0x0800, 0);
	if (PB_IP4(reply)->proto != 1 || PB_ICMP(reply)->type != 3 ||
			PB_ICMP(reply)->code != 3 || !icmp_checksum_valid(reply) ||
			memcmp(PB_ICMP_DATA(reply), quoted, sizeof(quoted))) {
		*why = "the response is not a valid ICMP Port Unreachable quoting the datagram";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

static void assert_udp_delivery(const struct test_state *state,
		uint8_t expected, uint16_t payload_len, uint8_t first_payload_byte)
{
	const struct test_event *event;

	assert(test_event_count(state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) == expected);
	if (!expected)
		return;
	event = test_event_nth(state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD, 0);
	assert(event && event->value[0] == 20000 &&
			event->value[1] == 10000 &&
			event->value[2] == payload_len &&
			event->value[3] == first_payload_byte);
}

static void udp_path_self_test(void)
{
	struct fixture f;
	const uint8_t payload[] = { 0xde, 0xad, 0xbe, 0xef, 0x42 };
	void *pkt;

	assert(fixture_init(&f));
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	assert(PB_IP4(pkt)->proto == 17);
	assert(PB_IP4_TOTAL_LEN(pkt) ==
			sizeof(struct iip_ip4_hdr) + sizeof(struct iip_udp_hdr) +
			sizeof(payload));
	assert(PB_UDP_TOTAL_LEN(pkt) == sizeof(struct iip_udp_hdr) +
			sizeof(payload));
	assert(!memcmp(PB_UDP_PAYLOAD(pkt), payload, sizeof(payload)));
	assert(ip4_checksum_valid(pkt));
	assert(udp_checksum_valid(pkt));
	fixture_deliver(&f, pkt);
	assert_udp_delivery(&f.state, 1, sizeof(payload), payload[0]);

	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP(pkt)->csum_be ^= ii_htons(1);
	fixture_deliver(&f, pkt);
	assert_udp_delivery(&f.state, 0, 0, 0);

	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP(pkt)->len_be = ii_htons(PB_UDP_TOTAL_LEN(pkt) - 1);
	fixture_deliver(&f, pkt);
	assert_udp_delivery(&f.state, 0, 0, 0);
	free_output(&f.state);
}

static void udp_fragment_limit_case(unsigned int fragment_count,
		uint8_t expect_delivery)
{
	struct fixture f;
	uint8_t *payload;
	void *datagram;
	void **fragments;
	uint16_t payload_len;
	uint16_t payload_offset = 0;
	unsigned int i;

	assert(fragment_count > 1);
	assert(fragment_count <= TEST_PKT_MAX);
	assert(fragment_count <= (UINT16_MAX - sizeof(struct iip_udp_hdr)) / 8);
	assert(fixture_init(&f));

	/*
	 * Keep the first fragment large enough to contain both the UDP header and
	 * one payload octet.  Every later fragment is the minimum legal 8 octets.
	 */
	payload_len = (uint16_t)(fragment_count * 8);
	payload = malloc(payload_len);
	fragments = calloc(fragment_count, sizeof(*fragments));
	assert(payload && fragments);
	for (i = 0; i < payload_len; i++)
		payload[i] = (uint8_t)(0xa5U + i);
	datagram = fixture_udp_packet(&f, payload, payload_len);
	assert(PB_IP4_TOTAL_LEN(datagram) - PB_IP4_HDR_LEN(datagram) ==
			(uint16_t)((fragment_count + 1) * 8));

	for (i = 0; i < fragment_count; i++) {
		uint16_t fragment_len = i ? 8 : 16;

		fragments[fragment_count - 1 - i] =
			fixture_ip4_fragment(&f, datagram,
				payload_offset, fragment_len,
				i + 1 < fragment_count);
		payload_offset += fragment_len;
	}
	iip_ops_pkt_free(datagram, &f.state);
	deliver(f.ws, f.local_mac, ii_htonl(f.conn->src_ip[0]), fragments,
			(uint16_t)fragment_count, &f.state);

	assert_udp_delivery(&f.state, expect_delivery, payload_len, payload[0]);
	free(payload);
	free(fragments);
	free_output(&f.state);
}

static void udp_fragment_limit_self_test(void)
{
	_Static_assert(II_CONF_IPV4_FRAG_CNT_MAX + 1 <= TEST_PKT_MAX,
			"fragment limit test exceeds the test packet array");
	udp_fragment_limit_case(II_CONF_IPV4_FRAG_CNT_MAX, 1);
	udp_fragment_limit_case(II_CONF_IPV4_FRAG_CNT_MAX + 1, 0);
}

static void arp_path_self_test(void)
{
	struct fixture f;
	const struct test_event *event;
	void *request, *reply;
	uint32_t sender_ip4_be, target_ip4_be;

	assert(fixture_init(&f));
	test_api_arp_request(f.ws, f.peer_mac, ii_htonl(f.conn->dst_ip[0]),
			ii_htonl(f.conn->src_ip[0]), &f.state);
	assert(f.state.out_cnt == 1);
	request = f.state.out[0];
	f.state.out_cnt = 0;
	assert(ii_ntohs(iip_ops_l2_ethertype_be(request, &f.state)) ==
			0x0806);
	assert(ii_ntohs(PB_ARP(request)->op_be) == 1);
	assert(!memcmp(iip_ops_l2_hdr_dst_ptr(request, &f.state),
			(uint8_t[]){ 0xff, 0xff, 0xff, 0xff, 0xff, 0xff }, 6));
	assert(!memcmp(PB_ARP_HW_SENDER(request), f.peer_mac, 6));
	memcpy(&sender_ip4_be, PB_ARP_IP_SENDER(request),
			sizeof(sender_ip4_be));
	memcpy(&target_ip4_be, PB_ARP_IP_TARGET(request),
			sizeof(target_ip4_be));
	assert(sender_ip4_be == ii_htonl(f.conn->dst_ip[0]));
	assert(target_ip4_be == ii_htonl(f.conn->src_ip[0]));

	fixture_deliver(&f, request);
	assert(f.state.out_cnt == 1);
	reply = f.state.out[0];
	f.state.out_cnt = 0;
	assert(ii_ntohs(PB_ARP(reply)->op_be) == 2);
	assert(!memcmp(iip_ops_l2_hdr_dst_ptr(reply, &f.state),
			f.peer_mac, 6));
	assert(!memcmp(PB_ARP_HW_SENDER(reply), f.local_mac, 6));
	memcpy(&sender_ip4_be, PB_ARP_IP_SENDER(reply),
			sizeof(sender_ip4_be));
	memcpy(&target_ip4_be, PB_ARP_IP_TARGET(reply),
			sizeof(target_ip4_be));
	assert(sender_ip4_be == ii_htonl(f.conn->src_ip[0]));
	assert(target_ip4_be == ii_htonl(f.conn->dst_ip[0]));

	{
		void *input[1] = { reply };
		deliver(f.ws, f.peer_mac, ii_htonl(f.conn->dst_ip[0]), input, 1, &f.state);
	}
	assert(test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_ARP_REPLY) == 1);
	event = test_event_nth(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_ARP_REPLY, 0);
	assert(event && event->value[0] == 2 &&
			event->value[1] == ii_htonl(f.conn->src_ip[0]) &&
			event->value[2] == ii_htonl(f.conn->dst_ip[0]));
	free_output(&f.state);
}


static void api_pump(struct iip_workspace *a, struct test_state *sa,
		struct iip_workspace *b, struct test_state *sb)
{
	uint32_t next;
	for (unsigned int round = 0; round < 8; round++) {
		unsigned int n = sa->out_cnt;
		void *input[TEST_PKT_MAX];
		memcpy(input, sa->out, n * sizeof(*input));
		sa->out_cnt = 0;
		assert(test_api_run(b, sb->local_mac, sb->local_ip4_be, input,
				(uint16_t)n, &next, sb) == n);
		n = sb->out_cnt;
		memcpy(input, sb->out, n * sizeof(*input));
		sb->out_cnt = 0;
		assert(test_api_run(a, sa->local_mac, sa->local_ip4_be, input,
				(uint16_t)n, &next, sa) == n);
		if (!sa->out_cnt && !sb->out_cnt) return;
	}
	assert(!"API smoke link did not become idle");
}

static void current_api_self_test(void)
{
	struct iip_workspace *a = calloc(1, sizeof(*a));
	struct iip_workspace *b = calloc(1, sizeof(*b));
	struct test_state sa = { 0 }, sb = { 0 };
	uint8_t amac[6] = { 2 }, bmac[6] = { 4 };
	uint32_t aip = ii_htonl(0xc0000201U), bip = ii_htonl(0xc6336402U);
	assert(a && b);
	test_workspace_init(a);
	test_workspace_init(b);
	sa.use_fake_clock = sb.use_fake_clock = 1;
	sa.now_ns = sb.now_ns = 1000000000ULL;
	sa.quiet_payload = sb.quiet_payload = 1;
	memcpy(sa.local_mac, amac, 6);
	memcpy(sb.local_mac, bmac, 6);
	sa.local_ip4_be = aip;
	sb.local_ip4_be = bip;
	assert(test_api_connect(a, amac, aip, ii_htons(10000), bmac,
			bip, ii_htons(20000), &sa) == 0);
	uint32_t next;
	assert(test_api_run(a, amac, aip, NULL, 0, &next, &sa) == 0);
	api_pump(a, &sa, b, &sb);
	assert(a->tcp_conns.array[0].state == II_TCP_STATE_ESTABLISHED);
	assert(b->tcp_conns.array[0].state == II_TCP_STATE_ESTABLISHED);
	assert(test_event_count(&sa, TEST_EVENT_CALLBACK, TEST_CALLBACK_CONNECTED) == 1);
	assert(test_event_count(&sb, TEST_EVENT_CALLBACK, TEST_CALLBACK_ACCEPTED) == 1);
	/* Exercise vector send and both receive callbacks through actual frames. */
	void *pkt = iip_ops_pkt_alloc(&sa);
	memcpy(iip_ops_pkt_get_data(pkt, &sa), (uint8_t[]){ 0, 1, 2, 3 }, 4);
	iip_ops_pkt_set_len(pkt, 4, &sa);
	assert(test_api_send(a, &a->tcp_conns.array[0], pkt, 0, &sa) == 0);
	assert(test_api_run(a, amac, aip, NULL, 0, &next, &sa) == 0);
	api_pump(a, &sa, b, &sb);
	assert(sb.payload_byte_count == 4 && sb.next_payload == 4);
	assert(a->tcp_conns.array[0].acked_seq == a->tcp_conns.array[0].seq);
	pkt = iip_ops_pkt_alloc(&sb);
	memcpy(iip_ops_pkt_get_data(pkt, &sb), (uint8_t[]){ 0, 1, 2, 3 }, 4);
	iip_ops_pkt_set_len(pkt, 4, &sb);
	assert(test_api_send(b, &b->tcp_conns.array[0], pkt, 0, &sb) == 0);
	assert(test_api_run(b, bmac, bip, NULL, 0, &next, &sb) == 0);
	api_pump(a, &sa, b, &sb);
	assert(sa.payload_byte_count == 4 && sa.next_payload == 4);
	/* CLOSE-WAIT callback closes the passive endpoint via its connection ID. */
	sb.close_wait.auto_close = 1;
	assert(test_api_close(a, &a->tcp_conns.array[0], &sa) == 0);
	assert(test_api_run(a, amac, aip, NULL, 0, &next, &sa) == 0);
	api_pump(a, &sa, b, &sb);
	assert(sb.close_wait.count == 1);
	assert(a->tcp_conns.array[0].state == II_TCP_STATE_TIME_WAIT);
	assert(b->tcp_conns.array[0].state == II_TCP_STATE_CLOSED);
	free_output(&sa);
	free_output(&sb);
	free(a);
	free(b);
}

static int run_self_tests(void)
{
	static const struct { const char *name; void (*run)(void); } tests[] = {
		{ "fake clock", fake_clock_self_test },
		{ "packet builder", packet_builder_self_test },
		{ "event log", event_log_self_test },
		{ "buffer shortage", buffer_shortage_self_test },
		{ "UDP paths", udp_path_self_test },
		{ "UDP fragment limit", udp_fragment_limit_self_test },
		{ "ARP paths", arp_path_self_test },
		{ "current API connect/data/close", current_api_self_test },
	};
	int failed = 0;
	for (unsigned int i = 0; i < ARRAY_LENGTH(tests); i++) {
		fflush(NULL);
		pid_t child = fork();
		assert(child >= 0);
		if (!child) { alarm(10); tests[i].run(); fflush(NULL); _exit(0); }
		if (!wait_test_child(child, 11000)) { fprintf(stderr, "Self-test failed: %s\n", tests[i].name); failed++; }
	}
	fprintf(stderr, "Self-test summary: %zu passed, %d failed\n", ARRAY_LENGTH(tests) - failed, failed);
	return failed != 0;
}

/*
 * The SACK regression runs in legacy_test_main, before this suite, because
 * it shares that two-endpoint setup.  Report its result as a TAP case so
 * that an assertion in its child process is not hidden from the summary.
 */
static enum result test_legacy_sack_generation(const char **why)
{
	(void)legacy_test_main();
	if (legacy_sack_tests_passed)
		return RESULT_PASS;
	*why = "SACK option did not match the expected blocks; RFC 2018 Section 4 requires the block containing the most recent segment first (see log)";
	return RESULT_FAIL;
}

